  const [rankA, zA] = paintRank(a);
  const [rankB, zB] = paintRank(b);
  return rankA - rankB || zA - zB || (domOrder.get(a.id) ?? 0) - (domOrder.get(b.id) ?? 0);
};
for (const siblings of childrenByParent.values()) siblings.sort(byPaintOrder);

