     const cdpStdout = chrome.stdio[4];
     if (!cdpStdin || !cdpStdout) throw new Error("Chrome did not expose its remote-debugging stdin/stdout pipes.");
     cdp = new CdpPipe(cdpStdin, cdpStdout, chrome);

